import { CheckCircleOutlined } from '@ant-design/icons'
import { OrderDetailData } from './types'
import { formatTime, isRetailOrder } from './constants'

interface OrderTimelineProps {
  orderDetail: OrderDetailData
}

interface TimelineStep {
  name: string
  time?: number
  completed: boolean
}

/**
 * 订单进度时间线组件
 */
const OrderTimeline: React.FC<OrderTimelineProps> = ({ orderDetail }) => {
  const isRetail = isRetailOrder(orderDetail.orderTypeId)
  const status = orderDetail.orderStatus

  // 根据订单类型定义不同的步骤
  const getSteps = (): TimelineStep[] => {
    if (isRetail) {
      // 零售订单：创建 -> 支付 -> 取货
      return [
        { name: '订单创建', time: orderDetail.storeTime, completed: true },
        { name: '已支付', time: orderDetail.storeTime, completed: status !== 1 },
        { name: '已取货', time: orderDetail.pickupTime, completed: status === 3 }
      ]
    }
    // 服务订单：创建 -> 存件 -> 取件
    return [
      { name: '订单创建', time: orderDetail.storeTime, completed: true },
      { name: '已存件', time: orderDetail.storeTime, completed: true },
      { name: '已取件', time: orderDetail.pickupTime, completed: status === 3 }
    ]
  }

  const steps = getSteps()

  return (
    <div
      style={{
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'center',
        gap: 0,
        padding: '12px 0'
      }}
    >
      {steps.map((step, index) => {
        const isLast = index === steps.length - 1
        const isCompleted = step.completed
        const nextCompleted = !isLast && steps[index + 1].completed
        const bgColor = isCompleted ? '#52C41A' : '#E2E8F0'

        return (
          <div key={index} style={{ display: 'flex', alignItems: 'center' }}>
            <div
              style={{
                display: 'flex',
                flexDirection: 'column',
                alignItems: 'center',
                minWidth: 100
              }}
            >
              <div
                style={{
                  width: 28,
                  height: 28,
                  borderRadius: '50%',
                  background: bgColor,
                  color: '#fff',
                  display: 'flex',
                  alignItems: 'center',
                  justifyContent: 'center',
                  fontSize: 12,
                  fontWeight: 600
                }}
              >
                {isCompleted ? <CheckCircleOutlined style={{ fontSize: 14 }} /> : index + 1}
              </div>
              <div style={{ fontSize: 12, fontWeight: 500, marginTop: 6 }}>{step.name}</div>
              <div style={{ fontSize: 10, color: '#999', marginTop: 2 }}>
                {step.time ? formatTime(step.time) : '-'}
              </div>
            </div>
            {!isLast && (
              <div
                style={{
                  width: 60,
                  height: 2,
                  background: nextCompleted ? '#52C41A' : '#E2E8F0',
                  margin: '0 12px',
                  marginBottom: 20
                }}
              />
            )}
          </div>
        )
      })}
    </div>
  )
}

export default OrderTimeline
