import { ProDescriptions } from '@ant-design/pro-components'
import { Tag, Badge, Space } from 'antd'
import { FileTextOutlined, EnvironmentOutlined, DollarCircleOutlined } from '@ant-design/icons'
import { ORDER_STATUS_MAP } from '@/constants'
import { OrderDetailData } from './types'
import { formatTime, ORDER_TYPE_MAP, isRetailOrder } from './constants'

interface BasicInfoProps {
  orderDetail: OrderDetailData
  /** 订单备注 */
  remark?: string
}

/**
 * 基本信息组件 - 包含费用信息和订单备注
 */
const BasicInfo: React.FC<BasicInfoProps> = ({ orderDetail, remark }) => {
  const orderType = ORDER_TYPE_MAP[orderDetail.orderTypeId]
  const isRetail = isRetailOrder(orderDetail.orderTypeId)

  const columns: any[] = [
    {
      title: '订单号',
      key: 'orderSn',
      dataIndex: 'orderSn',
      render: (dom: React.ReactNode) => (
        <span style={{ fontFamily: 'Courier New, monospace', fontWeight: 600 }}>
          {dom}
        </span>
      )
    },
    {
      title: '订单类型',
      key: 'orderTypeName',
      dataIndex: 'orderTypeName',
      render: (dom: React.ReactNode) => {
        const IconComponent = orderType?.icon
        return (
          <Tag color={orderType?.color || 'default'}>
            {IconComponent && (
              <span style={{ marginRight: 4 }}>
                <IconComponent />
              </span>
            )}
            {dom}
          </Tag>
        )
      }
    },
    {
      title: '订单状态',
      key: 'orderStatus',
      dataIndex: 'orderStatus',
      render: (dom: React.ReactNode, entity: OrderDetailData) => {
        const status = entity.orderStatus
        const statusConfig = ORDER_STATUS_MAP[status]
        const badgeStatus = (statusConfig?.status || 'default') as
          | 'success'
          | 'error'
          | 'warning'
          | 'default'
          | 'processing'
        return <Badge status={badgeStatus} text={statusConfig?.text || '未知'} />
      }
    },
    {
      title: isRetail ? '下单时间' : '存件时间',
      key: 'storeTime',
      dataIndex: 'storeTime',
      render: (dom: React.ReactNode, entity: OrderDetailData) => formatTime(entity.storeTime)
    },
    {
      title: isRetail ? '取货时间' : '取件时间',
      key: 'pickupTime',
      dataIndex: 'pickupTime',
      render: (dom: React.ReactNode, entity: OrderDetailData) =>
        entity.pickupTime ? formatTime(entity.pickupTime) : isRetail ? '待取货' : '待取件'
    },
    {
      title: '小区',
      key: 'communityName',
      dataIndex: 'communityName',
      render: (dom: React.ReactNode) => (
        <Space>
          <EnvironmentOutlined style={{ color: '#1890ff' }} />
          <span>{dom}</span>
        </Space>
      )
    },
    {
      title: '费用信息',
      key: 'orderAmount',
      render: (dom: React.ReactNode, entity: OrderDetailData) => (
        <Space size="large">
          <span>
            <DollarCircleOutlined style={{ color: '#1890ff', marginRight: 4 }} />
            <span style={{ color: '#666' }}>订单金额：</span>
            <span style={{ fontWeight: 600, color: '#1890ff' }}>¥{entity.orderAmount.toFixed(2)}</span>
          </span>
          <span>
            <span style={{ color: '#666' }}>实付：</span>
            <span style={{ fontWeight: 600, color: '#52C41A' }}>¥{entity.orderAmount.toFixed(2)}</span>
          </span>
        </Space>
      )
    }
  ]

  // 如果有备注，添加备注行
  if (remark) {
    columns.push({
      title: '订单备注',
      key: 'remark',
      render: () => (
        <div
          style={{
            padding: '8px 12px',
            background: '#FEFCE8',
            borderRadius: 4,
            border: '1px solid #FEF08A',
            fontSize: 12,
            color: '#1E293B',
            lineHeight: 1.4,
            display: 'inline-block'
          }}
        >
          <FileTextOutlined style={{ marginRight: 4, color: '#FAAD14' }} />
          {remark}
        </div>
      )
    })
  }

  return (
    <ProDescriptions
      column={2}
      size="small"
      dataSource={orderDetail}
      columns={columns}
    />
  )
}

export default BasicInfo