import { ProDescriptions } from '@ant-design/pro-components'
import { Tag } from 'antd'
import { LockOutlined } from '@ant-design/icons'
import { OrderDetailData } from './types'
import { GRID_SPEC_MAP } from './constants'

interface CabinetInfoProps {
  orderDetail: OrderDetailData
  /** 取件码 */
  pickupCode?: string
}

/**
 * 柜机信息组件 - 包含取件码
 */
const CabinetInfo: React.FC<CabinetInfoProps> = ({ orderDetail, pickupCode }) => {
  const columns: any[] = [
    {
      title: '设备编号',
      key: 'cabinetDeviceId',
      dataIndex: 'cabinetDeviceId',
      render: (dom: React.ReactNode) => (
        <span style={{ fontFamily: 'Courier New, monospace', fontWeight: 600 }}>
          {dom}
        </span>
      )
    },
    {
      title: '设备名称',
      key: 'cabinetName',
      dataIndex: 'cabinetName'
    },
    {
      title: '格口编号',
      key: 'gridNo',
      dataIndex: 'gridNo',
      render: (dom: React.ReactNode) => (
        <span style={{ fontFamily: 'Courier New, monospace', fontWeight: 600 }}>
          {dom}
        </span>
      )
    },
    {
      title: '格口规格',
      key: 'gridNo',
      dataIndex: 'gridNo',
      render: (dom: React.ReactNode, entity: OrderDetailData) => {
        const spec = String(entity.gridNo).charAt(0).toUpperCase()
        return <Tag color="blue">{GRID_SPEC_MAP[spec] || '未知'}</Tag>
      }
    }
  ]

  // 如果有取件码，添加取件码行
  if (pickupCode) {
    columns.push({
      title: '取件码',
      key: 'pickupCode',
      render: () => (
        <span style={{ fontFamily: 'Courier New, monospace', fontWeight: 700, fontSize: 16, color: '#1890ff', letterSpacing: 4 }}>
          <LockOutlined style={{ marginRight: 4, fontSize: 12 }} />
          {pickupCode}
        </span>
      )
    })
  }

  return (
    <ProDescriptions
      column={2}
      size="small"
      dataSource={orderDetail}
      columns={columns}
    />
  )
}

export default CabinetInfo