import type { ComponentType } from 'react'
import {
  InboxOutlined,
  ShoppingOutlined,
  ShoppingCartOutlined,
  FileTextOutlined
} from '@ant-design/icons'
import dayjs from 'dayjs'

/** 订单类型配置 */
export interface OrderTypeConfig {
  text: string
  color: string
  icon: ComponentType
}

/** 订单类型映射 */
export const ORDER_TYPE_MAP: Record<number, OrderTypeConfig> = {
  1: { text: '物品暂存', color: 'blue', icon: InboxOutlined },
  2: { text: '网购退货', color: 'purple', icon: ShoppingOutlined },
  3: { text: '包裹投递', color: 'cyan', icon: ShoppingCartOutlined },
  4: { text: '包裹揽收', color: 'geekblue', icon: ShoppingOutlined },
  5: { text: '商品寄售', color: 'orange', icon: ShoppingOutlined },
  6: { text: '信报投递', color: 'green', icon: FileTextOutlined }
}

/** 格口规格映射 */
export const GRID_SPEC_MAP: Record<string, string> = {
  S: '小格',
  M: '中格',
  L: '大格'
}

/** 格式化时间戳 */
export const formatTime = (timestamp?: number): string => {
  if (!timestamp) {
    return '-'
  }
  return dayjs(timestamp * 1000).format('YYYY-MM-DD HH:mm:ss')
}

/** 判断是否为零售订单 */
export const isRetailOrder = (orderTypeId: number): boolean => orderTypeId === 5
