import { useEffect, useState } from 'react'
import { useParams, useNavigate } from 'react-router-dom'
import {
  getOrderDetail,
  getOrderComplaintRecord,
  getOrderOperationLogs,
  OrderManagementTypes
} from '@/apis/admin/order-management'
import { PageContainer, ProCard } from '@ant-design/pro-components'
import { Button, message, Tag, Space, Spin, Empty } from 'antd'
import {
  ArrowLeftOutlined,
  ClockCircleOutlined,
  InboxOutlined,
  FileTextOutlined,
  UserOutlined
} from '@ant-design/icons'
import { ResultEnum } from '@/utils/enums/httpEnum'
import { ORDER_STATUS_MAP } from '@/constants'
import {
  OrderTimeline,
  BasicInfo,
  CabinetInfo,
  ComplaintRecord,
  OperationLog,
  isRetailOrder
} from './components/OrderDetail'

const OrderDetail: React.FC = () => {
  const { id } = useParams<{ id: string }>()
  const navigate = useNavigate()
  const [orderDetail, setOrderDetail] = useState<OrderManagementTypes.DetailOrderRes | null>(null)
  const [complaintRecords, setComplaintRecords] = useState<
    OrderManagementTypes.OrderComplaintRecordDto[]
  >([])
  const [operationLogs, setOperationLogs] = useState<OrderManagementTypes.OrderOperationLogDto[]>(
    []
  )
  const [loading, setLoading] = useState(true)

  // 获取订单详情
  const fetchOrderDetail = async () => {
    if (!id) {
      return
    }
    try {
      setLoading(true)
      const res = await getOrderDetail(Number(id))
      if (res.code === ResultEnum.SUCCESS && res.data) {
        setOrderDetail(res.data)
      } else {
        message.error('获取订单详情失败')
      }
    } catch (e) {
      console.error('获取订单详情失败:', e)
      message.error('获取订单详情失败')
    } finally {
      setLoading(false)
    }
  }

  // 获取客诉记录
  const fetchComplaintRecords = async () => {
    if (!id) {
      return
    }
    try {
      const res = await getOrderComplaintRecord(Number(id))
      if (res.code === ResultEnum.SUCCESS && res.data?.list) {
        setComplaintRecords(res.data.list)
      }
    } catch (e) {
      console.error('获取客诉记录失败:', e)
    }
  }

  // 获取操作日志
  const fetchOperationLogs = async () => {
    if (!id) {
      return
    }
    try {
      const res = await getOrderOperationLogs(Number(id))
      if (res.code === ResultEnum.SUCCESS && res.data?.List) {
        setOperationLogs(res.data.List)
      }
    } catch (e) {
      console.error('获取操作日志失败:', e)
    }
  }

  useEffect(() => {
    fetchOrderDetail()
    fetchComplaintRecords()
    fetchOperationLogs()
  }, [id])

  if (loading) {
    return (
      <PageContainer>
        <div
          style={{ display: 'flex', justifyContent: 'center', alignItems: 'center', height: 400 }}
        >
          <Spin size="large" tip="加载中..." />
        </div>
      </PageContainer>
    )
  }

  if (!orderDetail) {
    return (
      <PageContainer>
        <div style={{ textAlign: 'center', padding: 40 }}>
          <Empty description="订单不存在或已被删除" />
          <Button type="primary" onClick={() => navigate('/order/list')} style={{ marginTop: 16 }}>
            返回订单列表
          </Button>
        </div>
      </PageContainer>
    )
  }

  const status = ORDER_STATUS_MAP[orderDetail.orderStatus]
  const isRetail = isRetailOrder(orderDetail.orderTypeId)
  const hasComplaint = complaintRecords.length > 0
  // 非零售订单显示取件码（v7.0 从接口获取 pickupCode）
  const pickupCode = !isRetail ? orderDetail.pickupCode : undefined

  return (
    <PageContainer
      header={{
        title: (
          <Space>
            <Button
              type="text"
              icon={<ArrowLeftOutlined />}
              onClick={() => navigate('/order/list')}
            >
              返回列表
            </Button>
            <span style={{ fontSize: 20, fontWeight: 600 }}>订单详情</span>
          </Space>
        ),
        breadcrumb: undefined
      }}
    >
      <Space direction="vertical" size="middle" style={{ width: '100%' }}>
        {/* 订单进度 */}
        <ProCard
          title={
            <Space>
              <ClockCircleOutlined style={{ color: '#1890ff' }} />
              订单进度
              <Tag color={status?.color} style={{ marginLeft: 8 }}>
                {status?.text}
              </Tag>
            </Space>
          }
          bordered
          headerBordered
        >
          <OrderTimeline orderDetail={orderDetail} />
        </ProCard>

        {/* 信息区域两列 - 左侧6:右侧4 */}
        <div style={{ display: 'grid', gridTemplateColumns: '3fr 2fr', gap: 16 }}>
          {/* 基本信息 - 包含费用和备注 */}
          <ProCard
            title={
              <Space>
                <FileTextOutlined style={{ color: '#1890ff' }} />
                基本信息
              </Space>
            }
            bordered
            headerBordered
          >
            <BasicInfo orderDetail={orderDetail} remark={orderDetail.orderRemark} />
          </ProCard>

          {/* 柜机信息 - 包含取件码 */}
          <ProCard
            title={
              <Space>
                <InboxOutlined style={{ color: '#1890ff' }} />
                柜机信息
              </Space>
            }
            bordered
            headerBordered
          >
            <CabinetInfo orderDetail={orderDetail} pickupCode={pickupCode} />
          </ProCard>
        </div>

        {/* 客诉记录 */}
        {hasComplaint && (
          <ProCard
            title={
              <Space>
                <UserOutlined style={{ color: '#ff4d4f' }} />
                客诉记录
                <Tag color="error">处理中</Tag>
                {orderDetail.complaintId && (
                  <Tag color="default">投诉编号: {orderDetail.complaintId}</Tag>
                )}
              </Space>
            }
            bordered
            headerBordered
          >
            <ComplaintRecord
              orderId={Number(id)}
              records={complaintRecords}
              onReplySuccess={fetchComplaintRecords}
            />
          </ProCard>
        )}

        {/* 操作日志 */}
        <ProCard
          title={
            <Space>
              <ClockCircleOutlined style={{ color: '#1890ff' }} />
              操作日志
            </Space>
          }
          bordered
          headerBordered
        >
          <OperationLog logs={operationLogs} />
        </ProCard>
      </Space>
    </PageContainer>
  )
}

export default OrderDetail
