import { useRef, useEffect, useState } from 'react'
import { SendOutlined } from '@ant-design/icons'
import { Button, Input, Divider, Avatar, message } from 'antd'
import { ComplaintRecord as ComplaintRecordType } from './types'
import { replyOrderComplaint, OrderManagementTypes } from '@/apis/admin/order-management'
import { ResultEnum } from '@/utils/enums/httpEnum'

const { TextArea } = Input

interface ComplaintRecordProps {
  /** 订单ID */
  orderId: number
  /** 客诉记录列表 */
  records: ComplaintRecordType[]
  /** 回复成功回调 */
  onReplySuccess?: () => void
}

/**
 * 客诉记录组件
 */
const ComplaintRecord: React.FC<ComplaintRecordProps> = ({
  orderId,
  records,
  onReplySuccess
}) => {
  const [replyContent, setReplyContent] = useState('')
  const [submitting, setSubmitting] = useState(false)
  const complaintListRef = useRef<HTMLDivElement>(null)

  // 滚动客诉列表到底部
  useEffect(() => {
    if (complaintListRef.current) {
      complaintListRef.current.scrollTop = complaintListRef.current.scrollHeight
    }
  }, [records])

  // 回复客诉
  const handleReplyComplaint = async () => {
    if (!replyContent.trim()) {
      message.warning('请输入回复内容')
      return
    }

    try {
      setSubmitting(true)
      const res = await replyOrderComplaint(orderId, {
        orderId: orderId,
        content: replyContent
      } as OrderManagementTypes.ReplyOrderComplaintReq)
      if (res.code === ResultEnum.SUCCESS) {
        message.success('回复成功')
        setReplyContent('')
        onReplySuccess?.()
      } else {
        message.error('回复失败')
      }
    } catch (e) {
      console.error('回复客诉失败:', e)
      message.error('回复失败')
    } finally {
      setSubmitting(false)
    }
  }

  return (
    <>
      <div
        ref={complaintListRef}
        style={{
          maxHeight: 320,
          overflowY: 'auto',
          padding: 12,
          background: '#FAFAFA',
          borderRadius: 6
        }}
      >
        {records.map((item) => {
          const isUser = item.userType === 1
          const isSystem = item.userType === 4

          if (isSystem) {
            return (
              <div key={item.id} style={{ textAlign: 'center', margin: '8px 0' }}>
                <span
                  style={{
                    fontSize: 11,
                    color: '#94A3B8',
                    background: '#F1F5F9',
                    padding: '2px 10px',
                    borderRadius: 10
                  }}
                >
                  {item.createdAt} {item.content}
                </span>
              </div>
            )
          }

          const bgColor = isUser ? '#F8FAFC' : '#EFF6FF'
          const borderColor = isUser ? '#E2E8F0' : '#BFDBFE'

          return (
            <div
              key={item.id}
              style={{
                display: 'flex',
                flexDirection: 'column',
                alignItems: isUser ? 'flex-start' : 'flex-end',
                marginBottom: 12
              }}
            >
              <div
                style={{
                  display: 'flex',
                  alignItems: 'flex-start',
                  gap: 6,
                  maxWidth: '85%',
                  flexDirection: isUser ? 'row' : 'row-reverse'
                }}
              >
                <Avatar
                  size="small"
                  style={{
                    background: isUser ? '#10B981' : '#2563EB',
                    flexShrink: 0
                  }}
                >
                  {item.userName.charAt(0)}
                </Avatar>
                <div
                  style={{
                    background: bgColor,
                    border: `1px solid ${borderColor}`,
                    borderRadius: 6,
                    padding: '8px 12px'
                  }}
                >
                  <div style={{ fontSize: 11, color: '#64748B', marginBottom: 2 }}>
                    {item.userName} · {item.createdAt}
                  </div>
                  <div style={{ fontSize: 12, color: '#1E293B', lineHeight: 1.4 }}>
                    {item.content}
                  </div>
                </div>
              </div>
            </div>
          )
        })}
      </div>
      <Divider style={{ margin: '10px 0' }} />
      <div style={{ display: 'flex', gap: 8 }}>
        <TextArea
          value={replyContent}
          onChange={(e) => setReplyContent(e.target.value)}
          placeholder="请输入回复内容..."
          autoSize={{ minRows: 2, maxRows: 4 }}
          style={{ flex: 1 }}
        />
        <Button
          type="primary"
          icon={<SendOutlined />}
          loading={submitting}
          onClick={handleReplyComplaint}
        >
          发送
        </Button>
      </div>
    </>
  )
}

export default ComplaintRecord
