import { CheckCircleOutlined } from '@ant-design/icons'
import { Timeline, Empty } from 'antd'
import { OperationLog as OperationLogType } from './types'

interface OperationLogProps {
  /** 操作日志列表 */
  logs: OperationLogType[]
}

/**
 * 操作日志组件 - 紧凑版
 */
const OperationLog: React.FC<OperationLogProps> = ({ logs }) => {
  return (
    <>
      {logs.length > 0 ? (
        <Timeline
          mode="left"
          style={{ paddingTop: 4 }}
          items={logs.map((log) => ({
            dot: <CheckCircleOutlined style={{ color: '#52C41A', fontSize: 12 }} />,
            children: (
              <div style={{ marginBottom: 4 }}>
                <div style={{ fontSize: 12, color: '#999', marginBottom: 2 }}>{log.logTime}</div>
                <div style={{ fontSize: 13, color: '#333' }}>{log.logCtx}</div>
              </div>
            )
          }))}
        />
      ) : (
        <Empty description="暂无操作日志" imageStyle={{ height: 60 }} />
      )}
    </>
  )
}

export default OperationLog